// --------------------------------------------------------------------------
// Small helpers
// --------------------------------------------------------------------------

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function byteLength(text) {
  return Buffer.byteLength(text, 'utf8');
}

function kilobytes(text) {
  const kb = byteLength(text) / 1024;
  return `${Math.round(kb)} KB`;
}

/**
 * The page shell. Self-contained: no scripts, no fonts, no images, nothing
 * loaded from anywhere. A page that needs nothing cannot leak the session id
 * in a Referer header to a third party.
 */
function page(title, bodyHtml) {
  return (
    '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n' +
    '<meta name="viewport" content="width=device-width, initial-scale=1">\n' +
    '<meta name="robots" content="noindex, nofollow">\n' +
    `<title>${escapeHtml(title)}</title>\n` +
    '<style>\n' +
    ':root{--ink:#1b1b1f;--muted:#5b5b66;--line:#dcd9d2;--paper:#fbfaf7;--accent:#8a4b2a}\n' +
    '*{box-sizing:border-box}\n' +
    'body{margin:0;background:var(--paper);color:var(--ink);' +
    'font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;' +
    'line-height:1.6;font-size:17px}\n' +
    '.wrap{max-width:44rem;margin:0 auto;padding:56px 22px 72px}\n' +
    '.label{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.72rem;' +
    'letter-spacing:.22em;text-transform:uppercase;color:var(--muted)}\n' +
    'h1{font-size:1.72rem;line-height:1.25;margin:14px 0 18px;letter-spacing:-.01em}\n' +
    'p{margin:0 0 14px}\n' +
    '.note{color:var(--muted);font-size:.94rem}\n' +
    '.files{list-style:none;padding:0;margin:26px 0 8px}\n' +
    '.files li{border:1px solid var(--line);background:#fff;border-radius:10px;' +
    'padding:16px 18px;margin-bottom:12px}\n' +
    '.files a{color:var(--accent);font-weight:600;text-decoration:none;font-size:1.04rem}\n' +
    '.files a:hover{text-decoration:underline}\n' +
    '.files span{display:block;color:var(--muted);font-size:.9rem;margin-top:4px}\n' +
    'code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.86rem;' +
    'background:#f2efe9;border:1px solid var(--line);border-radius:5px;padding:1px 5px}\n' +
    '.rule{border:0;border-top:1px solid var(--line);margin:34px 0 18px}\n' +
    'footer{color:var(--muted);font-size:.86rem}\n' +
    'footer a{color:var(--muted)}\n' +
    '</style>\n</head>\n<body>\n<div class="wrap">\n' +
    '<p class="label">PromptDrawer</p>\n' +
    bodyHtml +
    '\n<hr class="rule">\n' +
    '<footer><p>Long&rsquo;s Holdings LLC &middot; <a href="/">back to the product page</a></p>' +
    '<p>This page is the whole delivery. No email is sent to you at any point - ' +
    'this business has no email system - and nothing here arranges one.</p></footer>\n' +
    '</div>\n</body>\n</html>\n'
  );
}

function sendHtml(res, status, htmlBody, reason) {
  res.statusCode = status;
  if (reason !== undefined) res.statusMessage = reason;
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store, max-age=0');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  // The pages use one inline <style> block and nothing else.
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
  );
  res.end(htmlBody);
}

function refuse(res, status, reason, title, paragraphs) {
  const body = paragraphs.map((text) => `<p>${text}</p>`).join('\n');
  sendHtml(res, status, page(title, `<h1>${escapeHtml(title)}</h1>\n${body}`), reason);
}

