/**
 * Retrieve a Checkout Session from Stripe with the server-side secret key.
 *
 * Returns { ok: true, paid: boolean, status: <payment_status> } or
 * { ok: false, kind: 'not-found' | 'refused' | 'unreachable' }.
 * Never throws; never returns the key or the raw Stripe payload to the caller.
 */
async function retrieveSession(sessionId, secretKey) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), STRIPE_TIMEOUT_MS);
  try {
    if (typeof fetch !== 'function') return { ok: false, kind: 'unreachable' };
    const response = await fetch(STRIPE_API + encodeURIComponent(sessionId), {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${secretKey}`,
        'Stripe-Version': '2024-06-20',
        Accept: 'application/json',
      },
      signal: controller.signal,
    });
    if (response.status === 404) return { ok: false, kind: 'not-found' };
    if (!response.ok) return { ok: false, kind: 'refused' };
    const session = await response.json();
    if (!session || session.object !== 'checkout.session') {
      return { ok: false, kind: 'refused' };
    }
    // The single gate. Note what is NOT read here: amount_total, currency,
    // payment_intent, customer, line items. Payment status is the only test.
    return {
      ok: true,
      paid: session.payment_status === 'paid',
      status: typeof session.payment_status === 'string' ? session.payment_status : 'unknown',
    };
  } catch (error) {
    return { ok: false, kind: 'unreachable' };
  } finally {
    clearTimeout(timer);
  }
}

// --------------------------------------------------------------------------
// The handler
// --------------------------------------------------------------------------

module.exports = async function handler(req, res) {
  const method = (req.method || 'GET').toUpperCase();
  if (method !== 'GET' && method !== 'HEAD') {
    res.setHeader('Allow', 'GET, HEAD');
    return refuse(
      res,
      405,
      'Method Not Allowed',
      'That request cannot download anything',
      [
        'This page is opened with a normal link in a browser, which is a GET request. ' +
          'Anything else is refused, so nothing was downloaded and nothing was changed.',
      ]
    );
  }

  let query;
  try {
    query = new URL(req.url, 'http://placeholder.invalid');
  } catch (error) {
    query = new URL('/api/download', 'http://placeholder.invalid');
  }

  const sessionId = (query.searchParams.get('session_id') || '').trim();
  const requestedFile = (query.searchParams.get('file') || '').trim().toLowerCase();

  if (requestedFile !== '' && requestedFile !== 'md' && requestedFile !== 'html') {
    return refuse(
      res,
      400,
      'Bad Request',
      'That is not one of the two files',
      [
        'This pack is exactly two files: <code>promptdrawer.md</code> (Markdown) and ' +
          '<code>promptdrawer.html</code> (print-ready). Those are the only names this page serves.',
        'Nothing was downloaded.',
      ]
    );
  }

  // 1. Is this deployment able to take money at all?
  const secretKey = process.env[STRIPE_KEY_ENV];
  if (!secretKey || !secretKey.trim()) {
    return refuse(
      res,
      503,
      'Service Unavailable',
      'Nothing has been purchased, and nothing can be downloaded',
      [
        'This page is the delivery point for PromptDrawer, but it is not switched on. No ' +
          'payment link is connected to it, so no purchase can have been recorded through it ' +
          'and there are no files for it to hand over.',
        'PromptDrawer itself is finished. Checkout is not open yet - payments onboarding for ' +
          'this business is not complete - so the pack cannot be bought anywhere today.',
        'Payments are not being taken at all yet. Nothing will ever be delivered to you by ' +
          'email: this business has no email system, and nothing here arranges one.',
      ]
    );
  }

  // 2. Is there a checkout reference to check?
  if (!sessionId) {
    return refuse(
      res,
      403,
      'Forbidden',
      'Nothing has been purchased, and nothing can be downloaded',
      [
        'This page needs the checkout reference that Stripe attaches to the link it sends you ' +
          'after a payment. This request arrived without one, so nothing has been purchased ' +
          'under it and nothing can be downloaded from it.',
        'The reference looks like <code>cs_test_&hellip;</code> or <code>cs_live_&hellip;</code> ' +
          'and appears at the end of the link.',
        'No email is sent to you at any point - this business has no email system - so if you ' +
          'think you are missing a message, the files are never delivered that way.',
      ]
    );
  }

  if (!SESSION_ID_SHAPE.test(sessionId)) {
    return refuse(
      res,
      403,
      'Forbidden',
      'Nothing has been purchased, and nothing can be downloaded',
      [
        'That is not the shape of a Stripe checkout reference, so no checkout can be looked up ' +
          'under it. Nothing has been purchased under it and nothing can be downloaded.',
        'A real one looks like <code>cs_test_&hellip;</code> or <code>cs_live_&hellip;</code> ' +
          'and comes from the payment link itself. Check the link for a copy-and-paste mistake.',
      ]
    );
  }

  // 3. The only question: did Stripe say this checkout is paid?
  const session = await retrieveSession(sessionId, secretKey.trim());

  if (!session.ok && session.kind === 'not-found') {
    return refuse(
      res,
      403,
      'Forbidden',
      'No checkout was found for that reference',
      [
        'Stripe does not know that checkout reference, so nothing has been purchased under it ' +
          'and nothing can be downloaded from it.',
        'The link may have been mistyped or truncated. The reference is the whole string at the ' +
          'end of the link, starting <code>cs_</code>.',
      ]
    );
  }

  if (!session.ok) {
    return refuse(
      res,
      502,
      'Bad Gateway',
      'This link could not be checked, so nothing can be downloaded',
      [
        'The payment could not be confirmed with Stripe just now, so no files are served from ' +
          'this link. That is a problem on this side, and it is not a statement that your ' +
          'payment failed - it means this page cannot currently tell whether the checkout was ' +
          'paid, and a page that cannot tell must not hand over the product.',
        'Nothing has been downloaded and nothing has been charged by this page. Try the same ' +
          'link again in a few minutes.',
        'Nothing is ever sent by email - this business has no email system.',
      ]
    );
  }

  if (!session.paid) {
    return refuse(
      res,
      403,
      'Forbidden',
      'No completed payment was found for this checkout, so nothing can be downloaded',
      [
        `Stripe reports this checkout as <code>${escapeHtml(session.status)}</code>. An abandoned ` +
          'checkout, an unpaid one and an expired one all look like this, so nothing has been ' +
          'purchased under this link and there are no files to hand over.',
        'Nothing has been charged by this page, and nothing will arrive by email - this business ' +
          'has no email system.',
      ]
    );
  }

  // 4. Paid. Serve the page, or the file that was asked for.
  if (requestedFile === '') {
    const body =
      '<h1>Payment confirmed &mdash; your files are ready</h1>\n' +
      '<p>Stripe reports this checkout as paid. Both files of PromptDrawer are below, and each ' +
      'one contains all 50 prompts in the same 8 categories.</p>\n' +
      '<ul class="files">\n' +
      `<li><a href="/api/download?session_id=${encodeURIComponent(sessionId)}&amp;file=md">` +
      `Download ${PACK_FILES.md.name}</a><span>Markdown &middot; ${kilobytes(PACK_FILES.md.body)} ` +
      '&middot; for pasting into any editor or AI assistant</span></li>\n' +
      `<li><a href="/api/download?session_id=${encodeURIComponent(sessionId)}&amp;file=html">` +
      `Download ${PACK_FILES.html.name}</a><span>Print-ready HTML &middot; ` +
      `${kilobytes(PACK_FILES.html.body)} &middot; opens in any browser and prints to PDF</span></li>\n` +
      '</ul>\n' +
      '<p class="note">Keep this page. It is the delivery point for this purchase and the same ' +
      'link works again later, so you can come back to it for another copy of either file.</p>\n' +
      '<p class="note">Nothing is sent to you by email: this business has no email system, so ' +
      'the files are delivered here and nowhere else.</p>\n' +
      `<p class="note">Checkout reference: <code>${escapeHtml(sessionId)}</code></p>`;
    return sendHtml(res, 200, page('PromptDrawer download', body));
  }

  const file = requestedFile === 'md' ? PACK_FILES.md : PACK_FILES.html;
  res.statusCode = 200;
  res.setHeader('Content-Type', file.contentType);
  res.setHeader('Content-Length', String(byteLength(file.body)));
  res.setHeader('Content-Disposition', `attachment; filename="${file.name}"`);
  res.setHeader('Cache-Control', 'no-store, max-age=0');
  res.setHeader('X-Robots-Tag', 'noindex, nofollow');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.end(file.body);
};
